            const y = Math.random() * 20 + 30;
            const z = (Math.random() - 0.5) * 60 + 32;

            this.positions[i * 3] = x;
            this.positions[i * 3 + 1] = y;
            this.positions[i * 3 + 2] = z;

            const vx = (Math.random() - 0.5) * this.speedLimit;
            const vy = (Math.random() - 0.5) * this.speedLimit;
