        const rightWing = new THREE.Mesh(rightWingGeo, material);
        rightWing.position.set(-0.15, 0.1, 0);
        meshGroup.add(rightWing);

        // Rotate so +Z is forward for simplified physics logic
        // Current model: 
        // Body length is Z (0.4). Head is at Z=0.25. 
