                alignX /= neighborCount; alignY /= neighborCount; alignZ /= neighborCount;
                cohX /= neighborCount; cohY /= neighborCount; cohZ /= neighborCount;
                cohX = (cohX - px); cohY = (cohY - py); cohZ = (cohZ - pz);
            }

