            const currentSpeedSq = vx * vx + vz * vz;
            if (currentSpeedSq < 0.1) {
                // If stopped, give random horizontal push
                const angle = Math.random() * Math.PI * 2;
                vx += Math.cos(angle) * 2;
                vz += Math.sin(angle) * 2;
            }

            // --- Speed Limit ---
            const speedSq = vx * vx + vy * vy + vz * vz;
            const speed = Math.sqrt(speedSq);

