            if (speed > this.speedLimit) {
                const ratio = this.speedLimit / speed;
                vx *= ratio;
                vy *= ratio;
                vz *= ratio;
            } else if (speed < this.speedMin) {
                const ratio = this.speedMin / speed;
                vx *= ratio;
                vy *= ratio;
                vz *= ratio;
            }

