        this.mesh.traverse(child => {
            if (child.isMesh) {
                child.castShadow = true;
                child.receiveShadow = true;
            }
        });
    }

    createWing(boneMat) {
        const wing = new THREE.Group();

        // Wing bone structure
        const upperBoneGeo = new THREE.BoxGeometry(0.2, 0.2, 1.5);
        const upperBone = new THREE.Mesh(upperBoneGeo, boneMat);
