            const pivot = new THREE.Group();
            pivot.position.set(x, 0.2, z); // Pivot at the top of the leg
            const leg = new THREE.Mesh(legGeo, beakMat);
            leg.position.set(0, -0.1, 0); // Offset leg relative to pivot
            pivot.add(leg);
            this.mesh.add(pivot);
            return pivot;
        };

        this.legParts = [
            makeLeg(-0.1, 0),
            makeLeg(0.1, 0)
        ];
    }

