            const targetY = Math.floor(pos.y) + 0.8;

            if (inWater) {
                this.velocity.y += 15.0 * dt; // Buoyancy
            } else {
                if (pos.y > targetY) {
                    this.velocity.y -= 10.0 * dt;
                } else {
                    this.velocity.y += 5.0 * dt;
                }
            }

