    }

    releaseBunny() {
        if (!this.carriedBunny) return;

        const bunny = this.carriedBunny;

        // Detach from trunk
        this.trunkTip.remove(bunny.mesh);

        // Get world position of trunk tip
        const worldPos = new THREE.Vector3();
        this.trunkTip.getWorldPosition(worldPos);

