        const legGeo = new THREE.BoxGeometry(0.5, 1.2, 0.5);
        const footGeo = new THREE.BoxGeometry(0.55, 0.15, 0.55);

        const makeLeg = (x, z) => {
            const pivot = new THREE.Group();
            pivot.position.set(x, 1.2, z);

