        const eyeGeo = new THREE.BoxGeometry(0.08, 0.08, 0.05);
        const leftEye = new THREE.Mesh(eyeGeo, flameMat);
        leftEye.position.set(-0.12, 0.8, 0.88);
        this.mesh.add(leftEye);

