        const makeLeg = (x, z) => {
            const pivot = new THREE.Group();
            pivot.position.set(x, 0.4, z);
            const leg = new THREE.Mesh(legGeo, mat);
            leg.position.set(0, -0.2, 0);
            pivot.add(leg);
            this.mesh.add(pivot);
            return pivot;
