        const bodyColor = 0xFFA500; // Orange
        const finColor = 0xFFFFFF; // White

        const mat = new THREE.MeshLambertMaterial({ color: bodyColor });
        const finMat = new THREE.MeshLambertMaterial({ color: finColor });

