        rightWing.position.set(bodyW / 2 + 0.05, 1.2, 0);
        this.mesh.add(rightWing);

        // Neck
        // Long curved neck - we'll simulate with 3 segments
        const neckW = 0.15;
        const neckSegGeo = new THREE.BoxGeometry(neckW, 0.5, neckW);

        // Neck 1 (Vertical from body)
        const neck1 = new THREE.Mesh(neckSegGeo, mat);
        neck1.position.set(0, 1.2 + bodyH / 2 + 0.25, 0.3); // Front of body
        this.mesh.add(neck1);

        // Neck 2 (Angled forward/up)
        const neck2 = new THREE.Mesh(neckSegGeo, mat);
        neck2.position.set(0, 1.7 + 0.2, 0.4);
        neck2.rotation.x = -0.5;
        this.mesh.add(neck2);

        // Neck 3 (Head Base)
        const neck3 = new THREE.Mesh(neckSegGeo, mat);
        neck3.position.set(0, 2.0, 0.6);
        neck3.rotation.x = -1.0;
        this.mesh.add(neck3);

        // Head
        const headGeo = new THREE.BoxGeometry(0.25, 0.25, 0.3);
        const head = new THREE.Mesh(headGeo, mat);
        head.position.set(0, 2.2, 0.7);
        this.mesh.add(head);

        // Beak (Curved down)
        const beakGeo1 = new THREE.BoxGeometry(0.15, 0.1, 0.2);
        const beak1 = new THREE.Mesh(beakGeo1, beakMat);
        beak1.position.set(0, 2.15, 0.95);
        beak1.rotation.x = 0.5;
        this.mesh.add(beak1);

        const beakGeo2 = new THREE.BoxGeometry(0.12, 0.1, 0.15);
        const beak2 = new THREE.Mesh(beakGeo2, beakTipMat);
        beak2.position.set(0, 2.05, 1.0);
        beak2.rotation.x = 1.0;
        this.mesh.add(beak2);

        // Eyes
        const eyeGeo = new THREE.BoxGeometry(0.05, 0.05, 0.02);
        const leftEye = new THREE.Mesh(eyeGeo, blackMat);
        leftEye.position.set(-0.13, 2.2, 0.75);
        this.mesh.add(leftEye);

        const rightEye = new THREE.Mesh(eyeGeo, blackMat);
        rightEye.position.set(0.13, 2.2, 0.75);
        this.mesh.add(rightEye);


        // Legs
        // Long thin legs
        const legW = 0.08;
        const legH = 1.2;
        const legGeo = new THREE.BoxGeometry(legW, legH, legW);

        // Left Leg
        const leftLeg = new THREE.Mesh(legGeo, legMat);
        leftLeg.position.set(-0.15, 0.6, 0);
        this.mesh.add(leftLeg);

        // Right Leg
        const rightLeg = new THREE.Mesh(legGeo, legMat);
        rightLeg.position.set(0.15, 0.6, 0);
        this.mesh.add(rightLeg);

        // Feet (Webbed-ish)
        const footGeo = new THREE.BoxGeometry(0.25, 0.05, 0.3);
        const leftFoot = new THREE.Mesh(footGeo, legMat);
        leftFoot.position.set(-0.15, 0.025, 0.05); // Flat on ground
        this.mesh.add(leftFoot);

        const rightFoot = new THREE.Mesh(footGeo, legMat);
        rightFoot.position.set(0.15, 0.025, 0.05);
        this.mesh.add(rightFoot);

        // Animation handles
        this.legParts = [leftLeg, rightLeg];
    }
}

import * as THREE from 'three';
import { Pegasus } from './Pegasus.js';

export class FlyingPegasus extends Pegasus {
    constructor(game, x, y, z, seed) {
        super(game, x, y, z, seed);
        this.gravity = 0;
        this.flying = true;
        this.targetAltitude = y + 10;
        this.flySpeed = 5;
        this.roamRadius = 30;

        // Target coordinates for flight
        this.targetX = x;
        this.targetZ = z;
        this.targetAltitude = y + 10;
    }

    updateAI(dt) {
        // Flying AI
        if (this.stateTimer <= 0) {
            this.stateTimer = this.rng.next() * 5 + 5;

            // Random target within roam radius
            const angle = this.rng.next() * Math.PI * 2;
            const dist = this.rng.next() * this.roamRadius;
            this.targetX = this.position.x + Math.cos(angle) * dist;
            this.targetZ = this.position.z + Math.sin(angle) * dist;

            // Random altitude between 10 and 25
            this.targetAltitude = 15 + (this.rng.next() * 15);
        }

        // Move towards target in 3D
        const target = new THREE.Vector3(this.targetX, this.targetAltitude, this.targetZ);
        const dir = target.clone().sub(this.position);
        const distToTarget = dir.length();

        if (distToTarget > 0.5) {
            dir.normalize();

            // Interpolate velocity for smoother movement
            const lerpFactor = 0.05;
            this.velocity.x += (dir.x * this.flySpeed - this.velocity.x) * lerpFactor;
            this.velocity.y += (dir.y * this.flySpeed - this.velocity.y) * lerpFactor;
            this.velocity.z += (dir.z * this.flySpeed - this.velocity.z) * lerpFactor;

            this.isMoving = true;

            // Look in movement direction
            const targetRotation = Math.atan2(this.velocity.x, this.velocity.z);
            let diff = targetRotation - this.rotation;
            while (diff < -Math.PI) diff += Math.PI * 2;
            while (diff > Math.PI) diff -= Math.PI * 2;
            this.rotation += diff * 0.1;
        } else {
            this.isMoving = false;
            this.velocity.multiplyScalar(0.95);
        }

        this.stateTimer -= dt;
    }

    updatePhysics(dt) {
        // Override physics to use 3D velocity and no gravity
        this.position.x += this.velocity.x * dt;
        this.position.y += this.velocity.y * dt;
        this.position.z += this.velocity.z * dt;

        // Don't fall through the floor
        const floorY = this.game.getWorldHeight ? this.game.getWorldHeight(this.position.x, this.position.z) : 0;
        if (this.position.y < floorY + 1) {
            this.position.y = floorY + 1;
            this.velocity.y = Math.max(0, this.velocity.y);
        }
    }

    updateAnimation(dt) {
        // Ensure wings flap fast while flying
        const originalIsMoving = this.isMoving;
        this.isMoving = true; // Always flapping while in the air
        super.updateAnimation(dt);
        this.isMoving = originalIsMoving;

        // Tilt body based on pitch
        if (this.bodyGroup) {
            const horizontalVel = new THREE.Vector2(this.velocity.x, this.velocity.z).length();
            const pitch = -Math.atan2(this.velocity.y, horizontalVel + 0.1);
            this.bodyGroup.rotation.x = pitch * 0.5;
        }
    }
}

