                } else if (face === 2) { // Left
                    sx = -width / 2 - 0.01;
                    sy = (Math.random() - 0.5) * height;
                    sz = (Math.random() - 0.5) * depth;
                    ry = Math.PI / 2;
                } else { // Right
                    sx = width / 2 + 0.01;
                    sy = (Math.random() - 0.5) * height;
                    sz = (Math.random() - 0.5) * depth;
                    ry = Math.PI / 2;
                }

                spot.position.set(sx, sy, sz);
                spot.rotation.y = ry;
                parentMesh.add(spot);
            }
        };

