        // Giraffe head position:
        // y: 3.5 + (neckLen/2 * cos(0.2)) = 4.7
        // z: 0.8 + (neckLen/2 * sin(0.2)) = 1.05
        const headX = 0;
        const headY = 4.8;
        const headZ = 1.2;

