        const smileGeo = new THREE.BoxGeometry(0.15, 0.03, 0.02);
        const smile = new THREE.Mesh(smileGeo, new THREE.MeshLambertMaterial({ color: 0xCC6666 }));
        smile.position.set(0, -0.1, 0.21);
