            }
        }

        // Handle climbing state
        if (this.isClimbing) {
            this.velocity.y = this.climbSpeed * this.climbDirection;
            this.isMoving = true;

            if (this.climbTimer <= 0) {
                this.isClimbing = false;
            }
            return;
        }

        // If in tree, do tree behaviors
        if (this.inTree) {
            this.seekingTree = false;

            // Tree scanning for jumps
            this.scanTimer -= dt;
