                this.scanTimer = 0.5 + Math.random() * 0.5;
                this.checkForTrees();
            }

            // Get terrain height for relative height calculations
            const terrainY = this.game.worldGen ? this.game.worldGen.getTerrainHeight(this.position.x, this.position.z) : 0;
