            // Force downward if they're too high
            if (this.velocity.y > -3) {
                this.velocity.y = -3; // Gentle but consistent downward velocity
            }
            this.isClimbing = false;
            this.isJumping = false;
        }

        super.updatePhysics(dt);
    }
}

