        // Nostrils
        const nostrilGeo = new THREE.BoxGeometry(0.05, 0.05, 0.02);
        const leftNostril = new THREE.Mesh(nostrilGeo, blackMat);
        leftNostril.position.set(-0.08, 0.8, 1.205); // Slightly in front of snout
