            transparent: true,
            depthTest: false
        });

        const sprite = new THREE.Sprite(spriteMaterial);
        sprite.scale.set(2.0, 0.5, 1);
        sprite.position.set(0, 1.5, 0); // Above pig
        sprite.visible = false;
        this.mesh.add(sprite);
        this.speechBubble = sprite;
    }

