    updateCarrying(pixie, dt, playerX, playerY, playerZ) {
        const pos = pixie.group.position;
        const vel = pixie.velocity;
        const target = pixie.target;

        if (!target || target.isDead || target.isDying) {
            this.resetToFlying(pixie);
