        const engineGeo = new THREE.CylinderGeometry(0.4, 0.3, 0.4, 16);
        const engine = new THREE.Mesh(engineGeo, matEngine);
        engine.position.set(0, -0.2, 0);
        this.rocketGroup.add(engine);

