        const flameGeo = new THREE.ConeGeometry(0.25, 0.8, 8);
        this.flame = new THREE.Mesh(flameGeo, matFlame);
        this.flame.position.set(0, -0.8, 0);
        this.flame.rotation.x = Math.PI; // Point down
        this.rocketGroup.add(this.flame);
    }

