// HMR test - 12:51 - with registry
export class Sheep extends Animal {
    constructor(game, x, y, z, seed) {
        super(game, x, y, z, seed);
        this.width = 0.9;
        this.height = 1.0;
        this.depth = 1.1; // Slightly longer
        this.woolMeshes = [];
        this.createBody();
        this.mesh.scale.set(0.9, 0.9, 0.9);
    }

    setColor(color) {
        const c = new THREE.Color(color);
        this.woolMeshes.forEach(mesh => {
            mesh.material = mesh.material.clone();
            mesh.material.color.set(c);
        });
    }

    createBody() {
        // Sheep: White wool, beige skin
        const woolColor = 0xFFFFFF; // White
        const skinColor = 0xE3CFB8; // Beige/Tan

        const woolMat = new THREE.MeshLambertMaterial({ color: woolColor });
        const skinMat = new THREE.MeshLambertMaterial({ color: skinColor });
        const blackMat = new THREE.MeshLambertMaterial({ color: 0x111111 });
        const eyeWhiteMat = new THREE.MeshLambertMaterial({ color: 0xFFFFFF });

        // Body (Wool)
        const bodyGeo = new THREE.BoxGeometry(0.9, 0.8, 1.3);
        const body = new THREE.Mesh(bodyGeo, woolMat);
        body.position.set(0, 0.8, 0);
        this.mesh.add(body);
        this.woolMeshes.push(body);

        // Head (Skin)
        const headGeo = new THREE.BoxGeometry(0.6, 0.6, 0.65);
        const head = new THREE.Mesh(headGeo, skinMat);
        head.position.set(0, 1.2, 0.85); // Up and forward
        this.mesh.add(head);

        // Wool on top of head
        const headWoolGeo = new THREE.BoxGeometry(0.65, 0.2, 0.6);
        const headWool = new THREE.Mesh(headWoolGeo, woolMat);
        headWool.position.set(0, 1.5, 0.85);
        this.mesh.add(headWool);
        this.woolMeshes.push(headWool);

        // Eyes
        const eyeGeo = new THREE.BoxGeometry(0.12, 0.12, 0.05);
        const pupilGeo = new THREE.BoxGeometry(0.06, 0.06, 0.06);

        // Left Eye
        const leftEye = new THREE.Mesh(eyeGeo, eyeWhiteMat);
        leftEye.position.set(-0.30, 1.3, 1.15); // Side of head
        this.mesh.add(leftEye);

        const leftPupil = new THREE.Mesh(pupilGeo, blackMat);
        leftPupil.position.set(-0.30, 1.3, 1.17);
        this.mesh.add(leftPupil);

        // Right Eye
        const rightEye = new THREE.Mesh(eyeGeo, eyeWhiteMat);
        rightEye.position.set(0.30, 1.3, 1.15);
        this.mesh.add(rightEye);

        const rightPupil = new THREE.Mesh(pupilGeo, blackMat);
        rightPupil.position.set(0.30, 1.3, 1.17);
        this.mesh.add(rightPupil);

        // Ears? (Often hidden or small on minecraft sheep, but let's add small bumps)
        // No, let's keep it simple like typical blocky sheep.

        // Legs (Skin)
        const legW = 0.25;
        const legH = 0.55;

        const legGeo = new THREE.BoxGeometry(legW, legH, legW);
        // Maybe some wool at the very top of leg? Simplified to just skin for now or mimic MC where it's skin.

        const makeLeg = (x, z) => {
            const pivot = new THREE.Group();
            pivot.position.set(x, 0.55, z); // Hip pivot

            const legMesh = new THREE.Mesh(legGeo, skinMat);
            legMesh.position.set(0, -legH / 2, 0);
            pivot.add(legMesh);

            this.mesh.add(pivot);
            return pivot;
        };

        // Legs positioned
        this.legParts = [
            makeLeg(-0.3, 0.4),  // Front L
            makeLeg(0.3, 0.4),   // Front R
            makeLeg(-0.3, -0.4), // Back L
            makeLeg(0.3, -0.4)   // Back R
        ];
    }
}

import * as THREE from 'three';
import { Animal } from '../Animal.js';
import { Arrow } from '../projectiles/Arrow.js';

export class Skeleton extends Animal {
    constructor(game, x, y, z) {
        super(game, x, y, z);
        this.width = 0.6;
        this.height = 1.95;
        this.depth = 0.6;
        this.speed = 1.8;
        this.health = 20;
        this.isHostile = true;
        this.attackRange = 12.0; // Ranged attack
        this.attackCooldown = 2.0;

        this.createBody();
    }

    createBody() {
        const boneMat = new THREE.MeshLambertMaterial({ color: 0xDDDDDD }); // Off-white bones

        // Head Group
        const headGroup = new THREE.Group();
        headGroup.position.set(0, 1.5, 0);
        this.mesh.add(headGroup);

        const headGeo = new THREE.BoxGeometry(0.45, 0.45, 0.45);
        const headMesh = new THREE.Mesh(headGeo, boneMat);
        headMesh.position.set(0, 0.22, 0);
        headGroup.add(headMesh);

        // Eyes (Dark sockets)
        const eyeMat = new THREE.MeshLambertMaterial({ color: 0x222222 });
        const eyeGeo = new THREE.BoxGeometry(0.1, 0.08, 0.05);
        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(-0.12, 0.25, 0.23);
        headGroup.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(0.12, 0.25, 0.23);
        headGroup.add(rightEye);

        // Mouth socket
        const mouthGeo = new THREE.BoxGeometry(0.2, 0.05, 0.05);
        const mouth = new THREE.Mesh(mouthGeo, eyeMat);
        mouth.position.set(0, 0.1, 0.23);
        headGroup.add(mouth);

        // Body (Ribs/Spine simplified)
        const bodyGeo = new THREE.BoxGeometry(0.4, 0.7, 0.2);
        const bodyMesh = new THREE.Mesh(bodyGeo, boneMat);
        bodyMesh.position.set(0, 1.15, 0);
        this.mesh.add(bodyMesh);

        // Limbs (Thin bones)
        const makeLimb = (x, y, isLeg = false) => {
            const pivot = new THREE.Group();
            pivot.position.set(x, y, 0);
            const h = 0.75;
            const geo = new THREE.BoxGeometry(0.1, h, 0.1);
            const mesh = new THREE.Mesh(geo, boneMat);
            mesh.position.set(0, -h / 2, 0);
            pivot.add(mesh);
            this.mesh.add(pivot);
            return pivot;
        };

        const leftArmPivot = makeLimb(-0.25, 1.4);
        const rightArmPivot = makeLimb(0.25, 1.4);
        const leftLegPivot = makeLimb(-0.12, 0.75, true);
        const rightLegPivot = makeLimb(0.12, 0.75, true);

        this.legParts = [leftLegPivot, rightLegPivot];
        this.armParts = [leftArmPivot, rightArmPivot];

        // Bow
        this.bow = this.createBow();
        rightArmPivot.children[0].add(this.bow);
    }

    createBow() {
        const bowGroup = new THREE.Group();
        const woodMat = new THREE.MeshLambertMaterial({ color: 0x8B4513 });
        const handleGeo = new THREE.BoxGeometry(0.04, 0.2, 0.05);
        const handle = new THREE.Mesh(handleGeo, woodMat);
        bowGroup.add(handle);

        const upperGeo = new THREE.BoxGeometry(0.03, 0.3, 0.04);
        const upper = new THREE.Mesh(upperGeo, woodMat);
        upper.position.set(0, 0.2, -0.05);
        upper.rotation.x = -0.4;
        bowGroup.add(upper);

        const lowerGeo = new THREE.BoxGeometry(0.03, 0.3, 0.04);
        const lower = new THREE.Mesh(lowerGeo, woodMat);
        lower.position.set(0, -0.2, -0.05);
        lower.rotation.x = 0.4;
        bowGroup.add(lower);

        bowGroup.position.set(0, -0.4, 0.1);
        bowGroup.rotation.y = -Math.PI / 2;
        return bowGroup;
    }

    attackPlayer(player) {
        // Ranged attack
        const startPos = this.position.clone();
        startPos.y += 1.5; // From bow level

        const targetPos = player.position.clone();
        targetPos.y += 1.0; // Aim for chest

        const dir = new THREE.Vector3().subVectors(targetPos, startPos).normalize();
        const speed = 0.8; // Slower for realistic projectile physics
        const velocity = dir.multiplyScalar(speed);

        const arrow = new Arrow(this.game, startPos, velocity, this);
        this.game.scene.add(arrow.mesh);
        if (!this.game.projectiles) this.game.projectiles = [];
        this.game.projectiles.push(arrow);

        // Simple arm animation
        this.armParts[0].rotation.x = -Math.PI / 2;
        this.armParts[1].rotation.x = -Math.PI / 2;
    }
}

