    ROLL_STABILITY: 0.8,   // Wings want to level
    YAW_STABILITY: 0.5,    // Weathervane effect

    // Stall behavior
    STALL_SHAKE_INTENSITY: 0.15,
    STALL_ROLL_TENDENCY: 2.0,  // Wing drop during stall

    // Camera settings
    CAMERA_DISTANCE: 18,
    CAMERA_HEIGHT_OFFSET: 5
};

