export class Toucan extends Animal {
    constructor(game, x, y, z, seed) {
        super(game, x, y, z, seed);
        this.width = 0.5;
        this.height = 0.6;
        this.depth = 0.4;
        this.speed = 3.0;
        this.jumpForce = 10;
        this.createBody();
        this.mesh.scale.set(0.7, 0.7, 0.7);

        // Flying behavior
        this.isFlying = false;
        this.flyTimer = 0;
        this.flapSpeed = 0;
        this.targetHeight = 0;
        this.perchTimer = 0;
