const NAMES = [
    "Arthur", "Bree", "Caleb", "Dora", "Elias", "Fae", "Gideon", "Hana", "Ivy", "Jared",
    "Kael", "Lyra", "Milo", "Nora", "Orin", "Piper", "Quinn", "Rowan", "Silas", "Tess",
