        this.mesh.add(rightEye);

        // Legs (Short!)
        const legGeo = new THREE.BoxGeometry(0.12, 0.25, 0.12);

        const makeLeg = (x, z) => {
            const pivot = new THREE.Group();
            pivot.position.set(x, 0.25, z); // Low pivot

            const leg = new THREE.Mesh(legGeo, mat);
            leg.position.set(0, -0.12, 0);
            pivot.add(leg);

            this.mesh.add(pivot);
            return pivot;
        };

        this.legParts = [
            makeLeg(-0.15, 0.4),
            makeLeg(0.15, 0.4),
            makeLeg(-0.15, -0.4),
            makeLeg(0.15, -0.4)
        ];
    }
}

