        this.updateSocial(dt);

        // Update speech bubble timer
        if (this.phraseTimer > 0) {
            this.phraseTimer -= dt;
            if (this.phraseTimer <= 0) {
                this.currentPhrase = null;
                this.updateSpeechBubble(null);
            }
